<script lang="ts">
  import { navigate } from '@hcengineering/ui'
  import type { Training } from '@hcengineering/training'
  import training from '../plugin'
  import { trainingRoute, TrainingRouteTab } from '../routing/routes/trainingRoute'
  import { canViewTrainingIncomingRequests, getCurrentEmployeeRef } from '../utils'
  import NestedSpecialView from './NestedSpecialView.svelte'

  export let object: Training

  $: if (!canViewTrainingIncomingRequests(object)) {
    navigate(trainingRoute.build({ id: object._id, tab: TrainingRouteTab.Overview }), true)
  }
</script>

<NestedSpecialView
  _class={training.class.TrainingRequest}
  space={object.space}
  baseQuery={{
    attachedTo: object._id,
    attachedToClass: object._class,
    collection: 'requests',
    trainees: getCurrentEmployeeRef(),
    canceledOn: null
  }}
  descriptors={[training.viewlet.TrainingIncomingRequests]}
/>
