import training, { type Training } from '@hcengineering/training'
import { canViewTraining } from './canViewTraining'
import { getClient } from '@hcengineering/presentation'
import { getCurrentEmployeeRef } from './getCurrentEmployeeRef'

export async function canViewTrainingOverview (trn: Training): Promise<boolean> {
  if (canViewTraining(trn)) {
    return true
  }

  const client = getClient()
  const trainingRequests = await client.findAll(training.class.TrainingRequest, {
    attachedTo: trn._id,
    trainees: getCurrentEmployeeRef()
  })

  return trainingRequests.some((req) => req.canceledOn == null)
}
